function UISecondConfirm:Awake()
    self.timeTickEvent = Events.AddListener(Constants.EventNames.EVENT_CONFIRM_TIME_TICK, function(orderId, text)
        if self.id and checkInt(self.id) == checkInt(orderId) then
            self:OnTimeTick(text)
        end
    end)
    UIEventProxy.Create(self.BtnOk.gameObject).onPointerClick = function()
        if self.confirmCB ~= nil and type(self.confirmCB) == 'function' then
            if not isNull(self.confirmCB) then
                KTool.SafeDelete(self.controller.gameObject)
                self.confirmCB()
            end
        else
            KTool.SafeDelete(self.controller.gameObject)
        end
    end

    UIEventProxy.Create(self.BtnCancel.gameObject).onPointerClick = function()
        if self.cancelCB ~= nil and type(self.cancelCB) == 'function' then
            if not isNull(self.cancelCB) then
                KTool.SafeDelete(self.controller.gameObject)
                self.cancelCB()
            end
        else
            KTool.SafeDelete(self.controller.gameObject)
        end
    end

    UIEventProxy.Create(self.btnClose.gameObject).onPointerClick = function()
        if self.bgForceClose then
            KTool.SafeDelete(self.controller.gameObject)
            return
        end
        if self.isBgClose then
            if self.cancelCB ~= nil and type(self.cancelCB) == 'function' then
                if not isNull(self.cancelCB) then
                    KTool.SafeDelete(self.controller.gameObject)
                    self.cancelCB()
                end
            else
                KTool.SafeDelete(self.controller.gameObject)
            end
        end
    end
    if not isNull(self.CanvasScaler) then
        KTool.CalculateScreenFit(self.CanvasScaler)
    end

    if not isNull(self.CardHeadNode) then
        KTool.SetActive(self.CardHeadNode.gameObject,false)
    end
end

function UISecondConfirm:OnTimeTick(text)
    if KTool.IsActive(self.SubTitle) then
        local text = string.format_size_tag(string.format_color_tag(text, '#d7184a'), 42)
        self.SubTitle.text = text
    end
end
---ShowHUD
---二次确认框显示调用方法
---@param textTip string @ 提示的内容
---@param subTitle string @ 子标题内容
---@param okCB fun():void @ 确认的回调
---@param cancelCB fun():void @ 取消的回调
---@param type number@ 窗口类型
---@param isBgClose boolean @ 是否点击背景关闭
---@param consumeVos table @ 消耗道具 {consumeId = , num = }
---@param SubText2 string @ 提示的内容2
---@param tickCB fun(isConfirmTick:boolean):void
---@param bgForceClose boolean 点击空白处强制关闭，不调用cancel事件
function UISecondConfirm:ShowHUD(textTip, subTitle, okCB, cancelCB, type, isBgClose, consumeVos, SubText2, tickCB, goodTipsType, bgForceClose)
    self.isBgClose = isBgClose
    self.bgForceClose = bgForceClose
    if isNull(type) then
        type = 1
    end
    type = checkInt(type)
    self._type = type
    self._goodTipsType = checkInt(goodTipsType)

    --[[
    local flagIconCancel = self.BtnCancel.transform:Find("Image")
    local flagIconOk = self.BtnOk.transform:Find("Image")
    ---@type Game.Native.Common.CommonButtonNode
    local cancelMb = KTool.GetComponent(self.BtnCancel.gameObject, typeof(CommonButtonNode))
    ---@type Game.Native.Common.CommonButtonNode
    local okMb = KTool.GetComponent(self.BtnOk.gameObject, typeof(CommonButtonNode))
    local t = IconImagePath[string.format('GROUP_%d', type)]
    okMb:SetButtonTxt(true, t[1].name)
    cancelMb:SetButtonTxt(true, t[2].name)
    KTool.GetOrAddComponent(flagIconOk.gameObject, typeof(ImageAlterable)):LoadSprite(string.format('uiatlas/common/%s.png', t[1].icon))
    KTool.GetOrAddComponent(flagIconCancel.gameObject, typeof(ImageAlterable)):LoadSprite(string.format('uiatlas/common/%s.png', t[2].icon))
    ]]
    local t = IconImagePath[string.format('GROUP_%d', type)]
    self.OkTxt.text = t[1].name
    self.CancelTxt.text = t[2].name

    self.confirmCB = okCB
    self.cancelCB = cancelCB

    --
    self.Description.text = checkString(textTip)
    if not string.isEmpty(subTitle) then
        KTool.SetActive(self.SubTitle.gameObject, true)
        self.SubTitle.text = subTitle
    end

    if not string.isEmpty(SubText2) then
        KTool.SetActive(self.SubTitle2.gameObject, true)
        self.SubTitle2.text = SubText2
    end

    ---第4种类型 带一个道具显示的逻辑
    if type == 4 
    or type == 6
    or type == 11 then
        if #checkTable(consumeVos) > 9 then
            KTool.SetActive(self.GoodIconNode.gameObject, false)
            KTool.SetActive(self.ScrollView, true)
            self:FillGoodsList(consumeVos, type)
        else
            self:FillGoods(consumeVos, type)
            KTool.SetActive(self.GoodIconNode.gameObject, true)
            KTool.SetActive(self.ScrollView, false)
        end
    ----咖啡厅人员管理编队界面 二次确认
    elseif type == 7 then
        if not isNull(consumeVos) then
            self:FillCardHeadIcon(consumeVos)
        end
    elseif type == 13 then
        if not isNull(consumeVos) then
            self:FillOriginalPrice(consumeVos)
        end
    end

    local isShowTick = (not isNull(tickCB)) --and type(tickCB) == "function"
    KTool.SetActive(self.Remind, isShowTick)
    if isShowTick then
        UIEventProxy.Create(self.BtnSwitch.gameObject).onPointerClick = function()
            self.isConfirmTick = not self.isConfirmTick
            CfUtils.SetUISwitchImage(self.BtnSwitch.transform, self.isConfirmTick and SwitchImgStatusTick.On or SwitchImgStatusTick.Off)
            tickCB(self.isConfirmTick)
        end
    end
end

