---FillGoods
---绘制物品
---@param goodVos table 消耗道具 {consumeId = , num = }
function UISecondConfirm:FillGoods(goodVos)
    if not goodVos then
        return
    end
    local num = table.count(goodVos)
    if num < 1 then
        return
    end
    for k, v in pairs(goodVos) do
        local go = CfUtils.InstantiateGo(self.GoodNode, self.GoodIconNode)
        if go then
            ---@type GoodNodeMB
            local scr = CfUtils.GetLuaScr(go, GoodsNodeMBPath)
            if scr then
                local consumeVo = v

                if isTable(consumeVo) then

                    if self._type == 6 then
                        local showText = consumeVo.num
                        scr:Reload({ goodsId = consumeVo.goodsId, isShowNo = true, text = showText })
                    elseif self._type == 11 then
                        scr:Reload(v)
                    else
                        local showText = ""
                        if isNotNull(consumeVo.forceText) then
                            showText = tostring(consumeVo.forceText)
                        else
                            local num = consumeVo.num or consumeVo.goodsNum
                            local id = consumeVo.id or consumeVo.goodsId
                            local hasNum = GoodsUtils.GetThingNo(id)
                            local formatStr = hasNum >= checkNumber(num) and '%s/%s' or '<color=#ff8383>%s</color>/%s'
                            showText = string.format(formatStr, hasNum, num)
                        end
                        scr:Reload({ goodsId = consumeVo.goodsId, isShowNo = true, text = showText })
                    end
                end
                --scr:SetBgActive(true)
                scr:SetClickButtonAction(function(goodsId)
                    if self.id then
                        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
                        if isTable(vo) then
                            GameUtils.ShowCommonGoodsTipsBoard(go.gameObject, vo.id, true)
                        end
                    end
                    if self._goodTipsType == 1 then
                        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
                        if isTable(vo) then
                            GameUtils.ShowCommonTipsBoard(go.gameObject, vo.name, vo.desc, vo.quality, vo.id, true)
                        end
                    elseif self._goodTipsType == 2 then
                        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
                        if isTable(vo) then
                            GameUtils.ShowCommonGoodsTipsBoard(go.gameObject, vo.id, true)
                        end
                    end
                end)
            end
            KTool.SetActive(go, true)
        end
    end
end

function UISecondConfirm:FillCardHeadIcon(vo)
    KTool.SetActive(self.CardHeadNode.gameObject,true)
    local env = CfUtils.GetLuaScr(self.CardHeadNode.gameObject,"Game.MaidCoffee.MaidCoffeeUIDialog.Cell.OverseaManageCardHeadNode")
    if env then
       env:RefreshCardHeadIcon(vo)
    end
end

---绘制物品列表
---@param goodVos table 消耗道具 {consumeId = , num = }
function UISecondConfirm:FillGoodsList(goodVos)
    self._goodsVos = goodVos
    if not self.ScrollView.IsListViewInit then
        self.ScrollView:InitGridView(#goodVos, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.LoopView, #goodVos)
    end
end

---列表处理
function UISecondConfirm:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem("Cell")
    local go = cell.transform:Find("GoodNode")
    if isNotNull(go) then
        local scr = CfUtils.GetLuaScr(go, GoodsNodeMBPath)
        if isNotNull(scr) then
            local consumeVo = self._goodsVos[index + 1]

            if isTable(consumeVo) then
                if self._type == 6 then
                    local showText = consumeVo.num
                    scr:Reload({ goodsId = consumeVo.goodsId, isShowNo = true, showText })
                elseif self._type == 11 then
                    scr:Reload(consumeVo)
                else
                    local showText = (consumeVo.forceText ~= nil and consumeVo.forceText or string.format('%s/%s', GoodsUtils.GetThingNo(consumeVo.goodsId), consumeVo.num))
                    scr:Reload({ goodsId = consumeVo.goodsId, isShowNo = true, text = showText })
                end
            end
            scr:SetClickButtonAction(function(goodsId)
                local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
                if isTable(vo) then
                    GameUtils.ShowCommonTipsBoard(go.gameObject, vo.name, vo.desc, vo.quality, vo.id)
                end
            end)
        end
    end
    return cell
end

--竹林用
function UISecondConfirm:FillTypeImage(imgPath)
    if not imgPath then
        return
    end

    CfUtils.FillImage(self.Imgbuff, imgPath)
end

function UISecondConfirm:FillOriginalPrice(consume)
    CfUtils.SetActive(self.Price, true)
    if checkInt(consume.price) > 0 then
        CfUtils.SetActive(self.PriceImgGoodsIcon, false)
        CfUtils.FillText(self.PriceTextNumber, CfUtils.GetCustomDisplayPrice(consume.windowsPriceId, consume.channelProductId, 36))
    else
        local prices = checkTable(consume.prices)
        local goodsId = prices[1].currency
        local goodsNum = prices[1].current
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
        CfUtils.SetActive(self.PriceImgGoodsIcon, true)
        CfUtils.FillImage(self.PriceImgGoodsIcon, goodsVo.photoPath)
        CfUtils.FillText(self.PriceTextNumber, goodsNum)
    end
end


function UISecondConfirm:OnDestroy()
    Events.RemoveListener(Constants.EventNames.EVENT_CONFIRM_TIME_TICK, self.timeTickEvent)
    self.timeTickEvent = nil
    if not isNull(self.loader) then
        self.loader:Release()
        self.loader = nil
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UISecondConfirm